import{_ as t,c as s,o as i,ag as a}from"./chunks/framework.ARG558ZT.js";const k=JSON.parse('{"title":"Runnable Python component collection","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/applied-ai/python/index.md","filePath":"workbench/applied-ai/python/index.md"}'),o={name:"workbench/applied-ai/python/index.md"};function n(r,e,d,c,l,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="runnable-python-component-collection" tabindex="-1">Runnable Python component collection <a class="header-anchor" href="#runnable-python-component-collection" aria-label="Permalink to “Runnable Python component collection”">​</a></h1><p>The canonical <code>study_ai/</code> modules and <code>lab_tests/</code> checks were extracted from existing teaching examples. The lessons display these exact files through includes. Earlier companion checks and their locked project were retained alongside them; <code>eval-fixture-v1.json</code> and <code>safe-log.json</code> are required fixture assets, not secrets.</p><h2 id="reproduce-verification" tabindex="-1">Reproduce verification <a class="header-anchor" href="#reproduce-verification" aria-label="Permalink to “Reproduce verification”">​</a></h2><p>Copy this directory to an owned practice location, then from that copied project:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANGSMITH_TRACING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LANGCHAIN_TRACING_V2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mypy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> basics.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_ai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANGSMITH_TRACING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LANGCHAIN_TRACING_V2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><p>The lock selects Python 3.13.11, SDK 3.35.1, Pydantic 2.14.1, pytest 9.1.1 and LangGraph 1.2.17. Runtime/dev tools share a study environment here; do not install it into an Autocode template. The project is loose modules run from its root, not an already-built distributable wheel. Each copied fixture must keep its runtime/schema/library assumptions together.</p><p>Tests use synthetic keys, SDK mock transports, temporary local files and owned loopback listeners/processes. They do not require a real provider key. Leave tracing export off. Tests in <code>lab_tests/</code> are reference checks; <strong>never modify a submission&#39;s <code>src/tests</code></strong>. A constrained environment may need explicit permission for the local socket/process cases; do not claim those passed if only in-process tests ran.</p><h2 id="source-groups-and-limits" tabindex="-1">Source groups and limits <a class="header-anchor" href="#source-groups-and-limits" aria-label="Permalink to “Source groups and limits”">​</a></h2><table tabindex="0"><thead><tr><th>Modules / tests</th><th>Contract demonstrated</th></tr></thead><tbody><tr><td><code>extraction</code>, <code>vector_search</code>, <code>hybrid_search</code>, <code>vector_store</code>, <code>evidence</code>, <code>retrieval_pipeline</code>, <code>context_counter</code></td><td>Bounded parsing, synthetic vector geometry, current authority/version, staged SQLite index lifecycle, exact citations and context admission</td></tr><tr><td><code>model_sdk</code>, <code>model_streaming</code>, <code>token_budgets</code></td><td>Real pinned SDK serialization/parsing through fake transport; no live model output/token measurement</td></tr><tr><td><code>note_tool</code>, <code>task_scope</code>, <code>secure_note_reader</code>, <code>provider_export</code></td><td>Complete bounded arguments, exact capabilities, current scoped reads, safe projection/output and trusted export policy</td></tr><tr><td><code>tool_state</code>, <code>workflow_budget</code>, <code>approved_write</code>, <code>spend_ledger</code>, <code>lookup_graph</code></td><td>Local persistence/CAS, exact approval/effect receipt, atomic local reservations and separately RAM-only graph snapshots</td></tr><tr><td><code>eval_cases</code>, <code>retrieval_metrics</code>, <code>eval_measurements</code>, <code>judge_checks</code>, <code>workflow_trace</code>, <code>audit_record</code></td><td>Authored dataset/metric arithmetic, fixed events, local audit invariants; not representative model quality or production tracing</td></tr><tr><td>Setup/domain/API/logging/deployment modules</td><td>Typed prerequisite boundaries and owned service lifecycle, with real local process checks</td></tr></tbody></table><p><code>evidence_messages.py</code> is a retained small context-serialization helper; the later <code>retrieval_pipeline</code> is the primary budgeted assembly path. <code>basics.py</code> and prerequisite modules remain because service checks import them. No duplicate production package was copied from another repository.</p><p>This collection does not supply an integrated generated-answer endpoint, multi-chunk persistent RAG service, authenticated approval UI, full artifact/checkpoint transaction, distributed worker claim/lease, live provider, ANN service or n8n engine. Those boundaries are explained and specified in <a href="./../../../practice/applied-ai/">P-334/P-335</a>. A narrow component test cannot certify a complete deployment.</p>`,11)])])}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
